  Definition sc_pro_post (sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra : word) (F : bvmap 5 word) (fc : bv 32)
      (LF : list fframe) (bs ioc D N lo shi : Z) (m : mem) : machine_state -> Prop :=
    fun ms' => exists (m2 : mem) (spa : Z) (gap : list cell) (p0 p8 p16 p32 p40 p48 p56 j16 j32 : list byte) (h3 : word) (ff fp : Z)
                      (a3' a4' a5' a6' a7' t0' t1' t2' t3' t4' t5' t6' : word),
      ms' = MS (mkR (Z_to_bv 64 P_SC_RET_MI) (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) (Z_to_bv 64 bs) (Z_to_bv 64 (ff + 32)) (Z_to_bv 64 0)
                    a3' a4' a5' a6' a7' (Z_to_bv 64 ff) (Z_to_bv 64 bs) (Z_to_bv 64 N) (Z_to_bv 64 D) (Z_to_bv 64 (ff + 32)) s7
                    (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) s11 t3' t4' t5' t6')
               F (Z_to_bv 64 P_A_SSVC_MAKE_IMPL) fc None m2 (seg_rom bsegs)
      /\ rw_cells bsegs m2 spa (sc_loc p0 p8 p16 ff p32 p40 p48 p56)
      /\ rw_cells bsegs m2 (spa + 64) gap /\ Z.of_nat (cells_size gap) = bv_unsigned sp + -96 - (spa + 64)
      /\ (spa = bv_unsigned sp + -160 \/ spa = bv_unsigned sp + -176)
      /\ rw_cells bsegs m2 (bv_unsigned sp + -96) (hz_saved s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra)
      /\ rw_cells bsegs m2 ff (sc_frm ff ioc fp h3 j16 j32) /\ rw_cells bsegs m2 (Z.shiftr ff 3 + 2147450880) sc_sh0 /\ rw_cells bsegs m2 fp [C1 (b8 1)]
      /\ accessible m2 (ff + 32) 56
      /\ stk bsegs m2 lo spa /\ mem_inv bsegs m2
      /\ as_RFS H ((1, ff, fp) :: LF) m2 /\ fresh_frame H LF 1 ff fp /\ ACONST m2 /\ stack0 m2 lo shi
      /\ munch ([(lo, bv_unsigned sp)]%Z ++ fr1_XS H ff fp) m m2 /\ wmono bsegs m m2.

  Lemma sc_pro' : forall (lo shi : Z) (LF : list fframe) (bs ioc D N : Z)
      (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
    a0 = Z_to_bv 64 bs -> a1 = Z_to_bv 64 ioc -> a2 = Z_to_bv 64 D -> a3 = Z_to_bv 64 N ->
    0 <= bs < 2^64 -> 0 <= ioc < 2^64 -> 0 <= D < 2^64 -> 0 <= N < 2^64 ->
    stk bsegs m lo (bv_unsigned sp) -> lo + ASTREAM_CTOR_STACK <= bv_unsigned sp -> aceil <= lo -> mem_inv bsegs m ->
    bv_unsigned sp mod 16 = 0 -> bv_unsigned sp <= 0x7fffffffffff -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m ->
    as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat -> stack0 m lo shi ->
    evt bsegs (sc_pro_post sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra F fc LF bs ioc D N lo shi m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 P_A_STREAM_CTOR) fc None m (seg_rom bsegs)).
